9	PARTICULAR PURPOSE. See LICENSE in the root of the software repository for the
10	full text of the License.
11	*/
12	
13	#ifndef TREM_HPP
14	#define TREM_HPP
15	
16	#include <pto/common/constants.hpp>
17	
18	namespace pto {
19	// Formula: remainder(a, b) = a - floor(a/b) * b
20	// Note: For fp32, after computing remainder, we check if result * divider < 0.
21	//       If signs differ, we add divider to result to ensure the result has the same sign as divider.
22	template <typename T, unsigned dstRowStride>
23	struct RemOp {
24	    PTO_INTERNAL static void RemF32Instr(
25	        __ubuf__ float* dst, __ubuf__ float* src0, __ubuf__ float* src1, __ubuf__ float* tmp, unsigned repeatTimes,
26	        unsigned validCols)
27	    {
28	        set_mask_count();
29	        set_vector_mask(0, validCols);
30	        vdiv(tmp, src0, src1, 1, 1, 1, 1, 8, 8, 8);
31	        pipe_barrier(PIPE_V);
32	
33	        vconv_f322f32f(tmp, tmp, 1, 1, 1, 8, 8);
34	        pipe_barrier(PIPE_V);
35	
36	        vmul(dst, tmp, src1, 1, 1, 1, 1, 8, 8, 8);
37	        pipe_barrier(PIPE_V);
38	
39	        vsub(dst, src0, dst, 1, 1, 1, 1, 8, 8, 8);
40	        pipe_barrier(PIPE_V);
41	        vmul(tmp, dst, src1, 1, 1, 1, 1, 8, 8, 8);
42	        pipe_barrier(PIPE_V);
43	
44	        // vcmpvs_lt must run in norm mask mode with explicit repeatTimes: unlike
45	        // arithmetic ops, the compare op does not auto-extend a single repeat to
46	        // the whole count (CANN CompareScalarCompute passes ceil(count*sizeof(T)/256)
47	        // repeats), so repeat=1 would only emit the first 64 bits of the packed
48	        // mask and leave stale UB in the rest.
49	        __ubuf__ uint8_t* cmpMask = reinterpret_cast<__ubuf__ uint8_t*>(tmp + dstRowStride);
50	        set_mask_norm();
51	        set_vector_mask(-1, -1);
52	        vcmpvs_lt(cmpMask, tmp, 0.0f, repeatTimes, 1, 1, 8, 8);
53	        pipe_barrier(PIPE_V);
54	        set_mask_count();
55	        set_vector_mask(0, validCols);
56	
57	        vadd(tmp, dst, src1, 1, 1, 1, 1, 8, 8, 8);
58	        pipe_barrier(PIPE_V);
59	
60	        // VSEL_TENSOR_TENSOR_MODE (2) reads the packed bitmask from UB through a
61	        // two-level address indirection: set_cmpmask must receive a buffer holding
62	        // the mask's address, replicated over cmpmaskLen uint32 lanes (64-bit for
63	        // B32, same convention as TSel). cmpMask occupies
64	        // dstRowStride..dstRowStride+maskFloats, addrBuf follows it, aligned to 32 bytes.
65	        unsigned maskBytes = CeilDivision(dstRowStride, BIT_TO_BYTE);
66	        unsigned maskFloats = CeilDivision(maskBytes, BLOCK_BYTE_SIZE) * BIT_TO_BYTE;
67	        constexpr unsigned cmpmaskLen = 2; // 64-bit address for B32 dtype
68	        __ubuf__ uint32_t* addrBuf = reinterpret_cast<__ubuf__ uint32_t*>(tmp + dstRowStride + maskFloats);
69	        uint32_t maskAddr = static_cast<uint32_t>(reinterpret_cast<int64_t>(cmpMask));
70	        set_vector_mask(0, cmpmaskLen);
71	        vector_dup(addrBuf, maskAddr, 1, 1, 1, 8, 0);
72	        pipe_barrier(PIPE_V);
73	        set_cmpmask(addrBuf);
74	        pipe_barrier(PIPE_V);
75	        set_vector_mask(0, validCols);
76	        vsel(dst, tmp, dst, 1, 1, 1, 1, 8, 8, 8, 2);
77	        pipe_barrier(PIPE_V);
78	    }
79	
80	    PTO_INTERNAL static void RemInt32Instr(
81	        __ubuf__ int32_t* dst, __ubuf__ int32_t* src0, __ubuf__ int32_t* src1, __ubuf__ int32_t* tmp,
82	        unsigned repeatTimes, unsigned validCols)
83	    {
84	        __ubuf__ float* dst_f = reinterpret_cast<__ubuf__ float*>(dst);
85	        __ubuf__ float* src0_f = reinterpret_cast<__ubuf__ float*>(src0);
86	        __ubuf__ float* src1_f = reinterpret_cast<__ubuf__ float*>(src1);
87	        __ubuf__ float* tmp_f = reinterpret_cast<__ubuf__ float*>(tmp);
88	
89	        set_mask_count();
90	        set_vector_mask(0, validCols);
91	
92	        vconv_s322f32(src0_f, src0, 1, 1, 1, 8, 8);
93	        vconv_s322f32(src1_f, src1, 1, 1, 1, 8, 8);
94	        pipe_barrier(PIPE_V);
95	
96	        vdiv(tmp_f, src0_f, src1_f, 1, 1, 1, 1, 8, 8, 8);
97	        pipe_barrier(PIPE_V);
98	
99	        vconv_f322s32f(tmp, tmp_f, 1, 1, 1, 8, 8);
100	        pipe_barrier(PIPE_V);
101	
102	        vconv_f322s32r(src0, src0_f, 1, 1, 1, 8, 8);
103	        vconv_f322s32r(src1, src1_f, 1, 1, 1, 8, 8);
104	        pipe_barrier(PIPE_V);
105	        vmul(dst, tmp, src1, 1, 1, 1, 1, 8, 8, 8);
106	        pipe_barrier(PIPE_V);
107	
108	        vsub(dst, src0, dst, 1, 1, 1, 1, 8, 8, 8);
109	        pipe_barrier(PIPE_V);
110	
111	        vconv_s322f32(dst_f, dst, 1, 1, 1, 8, 8);
112	        vconv_s322f32(src1_f, src1, 1, 1, 1, 8, 8);
113	        pipe_barrier(PIPE_V);
114	        vmul(tmp_f, dst_f, src1_f, 1, 1, 1, 1, 8, 8, 8);
115	        pipe_barrier(PIPE_V);
116	
117	        // Same norm-mode compare with explicit repeatTimes as the f32 path.
118	        __ubuf__ uint8_t* cmpMask = reinterpret_cast<__ubuf__ uint8_t*>(tmp + dstRowStride);
119	        set_mask_norm();
120	        set_vector_mask(-1, -1);
121	        vcmpvs_lt(cmpMask, tmp_f, 0.0f, repeatTimes, 1, 1, 8, 8);
122	        pipe_barrier(PIPE_V);
123	        set_mask_count();
124	        set_vector_mask(0, validCols);
125	
126	        vadd(tmp_f, dst_f, src1_f, 1, 1, 1, 1, 8, 8, 8);
127	        pipe_barrier(PIPE_V);
128	
129	        // VSEL_TENSOR_TENSOR_MODE (2): same 64-bit address buffer as the f32 path.
130	        unsigned maskByte = CeilDivision(dstRowStride, BIT_TO_BYTE); // shape
131	        unsigned maskFloat = CeilDivision(maskByte, BLOCK_BYTE_SIZE) * BIT_TO_BYTE;
132	        constexpr unsigned cmpmaskLen = 2; // 64-bit address for B32 dtype
133	        __ubuf__ uint32_t* addrBufs = reinterpret_cast<__ubuf__ uint32_t*>(tmp + dstRowStride + maskFloat);
134	        uint32_t maskAddr = static_cast<uint32_t>(reinterpret_cast<int64_t>(cmpMask));
135	        set_vector_mask(0, cmpmaskLen);
136	        vector_dup(addrBufs, maskAddr, 1, 1, 1, 8, 0);
137	        pipe_barrier(PIPE_V);
138	        set_cmpmask(addrBufs);
139	        pipe_barrier(PIPE_V);
140	        set_vector_mask(0, validCols);
141	        vsel(dst_f, tmp_f, dst_f, 1, 1, 1, 1, 8, 8, 8, 2);
142	        pipe_barrier(PIPE_V);
143	
144	        vconv_f322s32z(dst, dst_f, 1, 1, 1, 8, 8);
145	        pipe_barrier(PIPE_V);
146	    }
147	
148	    PTO_INTERNAL static void RemInstr(
149	        __ubuf__ T* dst, __ubuf__ T* src0, __ubuf__ T* src1, __ubuf__ T* tmp, unsigned repeatTimes, unsigned validCols)
150	    {
151	        if constexpr (std::is_same_v<T, float> || std::is_same_v<T, float32_t>) {
152	            RemF32Instr(dst, src0, src1, tmp, repeatTimes, validCols);
153	        } else if constexpr (std::is_same_v<T, int32_t>) {
154	            RemInt32Instr(dst, src0, src1, tmp, repeatTimes, validCols);
155	        }
156	    }
157	};
158	
159	template <
160	    typename TileDataDst, typename TileDataSrc0, typename TileDataSrc1, typename TileDataTmp,
161	    unsigned elementsPerRepeat, unsigned blockSizeElem, unsigned dstRowStride, unsigned src0RowStride = dstRowStride,
162	    unsigned src1RowStride = dstRowStride>
163	__tf__ PTO_INTERNAL void TRem(
164	    typename TileDataDst::TileDType __out__ dst, typename TileDataSrc0::TileDType __in__ src0,
165	    typename TileDataSrc1::TileDType __in__ src1, typename TileDataTmp::TileDType __in__ tmp, unsigned validRows,
166	    unsigned validCols)
167	{
168	    using T = typename TileDataDst::DType;
169	    __ubuf__ T* dstPtr = (__ubuf__ T*)__cce_get_tile_ptr(dst);
170	    __ubuf__ T* src0Ptr = (__ubuf__ T*)__cce_get_tile_ptr(src0);
171	    __ubuf__ T* src1Ptr = (__ubuf__ T*)__cce_get_tile_ptr(src1);
172	    __ubuf__ T* tmpPtr = (__ubuf__ T*)__cce_get_tile_ptr(tmp);
173	
174	    constexpr unsigned tmpRowStride = TileDataTmp::RowStride;
175	    uint16_t repeatTimes = CeilDivision(validCols, elementsPerRepeat);
176	
177	    for (uint16_t i = 0; i < validRows; i++) {
178	        __ubuf__ T* dstNext = dstPtr + i * dstRowStride;
179	        __ubuf__ T* s0Next = src0Ptr + i * src0RowStride;
180	        __ubuf__ T* s1Next = src1Ptr + i * src1RowStride;
181	
182	        RemOp<T, dstRowStride>::RemInstr(dstNext, s0Next, s1Next, tmpPtr, repeatTimes, validCols);
183	        set_mask_norm();
184	        set_vector_mask(-1, -1);
185	    }
186	}
187	
188	template <typename T, typename TileDataDst, typename TileDataSrc0, typename TileDataSrc1, typename TileDataTmp>
189	PTO_INTERNAL void TRemCheck(
190	    const TileDataDst& dst, const TileDataSrc0& src0, const TileDataSrc1& src1, const TileDataTmp& tmp)
191	{
192	    static_assert(
193	        std::is_same_v<T, float> || std::is_same_v<T, float32_t> || std::is_same_v<T, int32_t>,
194	        "Fix: TREM supports only float and int32 element types.");
195	    static_assert(
196	        std::is_same_v<T, typename TileDataSrc0::DType> && std::is_same_v<T, typename TileDataSrc0::DType>,
197	        "Fix: TREM type of dst must be same with src0 and src1.");
198	    static_assert(
199	        TileDataDst::isRowMajor && TileDataSrc0::isRowMajor && TileDataSrc1::isRowMajor,
200	        "Fix: TREM support only row major layout.");
201	    unsigned validRows = dst.GetValidRow();
202	    unsigned validCols = dst.GetValidCol();
203	    PTO_ASSERT(
204	        src0.GetValidRow() == validRows && src0.GetValidCol() == validCols,
205	        "Fix: TREM input tile src0 valid shape mismatch with output tile dst shape.");
206	    PTO_ASSERT(
207	        src1.GetValidRow() == validRows && src1.GetValidCol() == validCols,
208	        "Fix: TREM input tile src1 valid shape mismatch with output tile dst shape.");
209	    // Single-row tmp layout: [0, dstRowStride) candidate, [dstRowStride, dstRowStride+maskFloats)
210	    // packed bitmask (32-byte aligned), then an 8-element (32-byte) address buffer.
211	    unsigned maskBytes = CeilDivision(TileDataDst::RowStride, BIT_TO_BYTE);
212	    unsigned maskFloats = CeilDivision(maskBytes, BLOCK_BYTE_SIZE) * BIT_TO_BYTE;
213	    unsigned tmpRequiredCols = TileDataDst::RowStride + maskFloats + BIT_TO_BYTE;
214	    PTO_ASSERT(
215	        tmp.GetValidRow() >= 1 && tmp.GetValidCol() >= tmpRequiredCols,
216	        "Fix: TREM tmp tile must have at least 1 row and enough columns for candidate, mask and address buffer.");
217	}
218	
219	template <
220	    auto PrecisionType = RemAlgorithm::DEFAULT, typename TileDataDst, typename TileDataSrc0, typename TileDataSrc1,
221	    typename TileDataTmp>
222	PTO_INTERNAL void TREM_IMPL(TileDataDst& dst, TileDataSrc0& src0, TileDataSrc1& src1, TileDataTmp& tmp)
223	{
224	    using T = typename TileDataDst::DType;
225	    TRemCheck<T, TileDataDst, TileDataSrc0, TileDataSrc1, TileDataTmp>(dst, src0, src1, tmp);
226	    constexpr unsigned blockSizeElem = BLOCK_BYTE_SIZE / sizeof(T);
227	    constexpr unsigned elementsPerRepeat = REPEAT_BYTE / sizeof(T);
228	    constexpr unsigned dstRowStride = TileDataDst::RowStride;
229	    constexpr unsigned src0RowStride = TileDataSrc0::RowStride;
230	    constexpr unsigned src1RowStride = TileDataSrc1::RowStride;
231	    TRem<
232	        TileDataDst, TileDataSrc0, TileDataSrc1, TileDataTmp, elementsPerRepeat, blockSizeElem, dstRowStride,
233	        src0RowStride, src1RowStride>(
234	        dst.data(), src0.data(), src1.data(), tmp.data(), dst.GetValidRow(), dst.GetValidCol());
235	}
