11	#ifndef TBIN_HPP
12	#define TBIN_HPP
13	
14	#include <pto/common/constants.hpp>
15	#include <pto/common/utils.hpp>
16	
17	namespace pto {
18	constexpr unsigned SMALL_RPT_BINOP = 4;
19	
20	template <typename Op, typename T>
21	PTO_INTERNAL void Bin1LCountMode(
22	    __ubuf__ T* dstPtr, __ubuf__ T* src0Ptr, __ubuf__ T* src1Ptr, unsigned validRow, unsigned validCol)
23	{
24	    set_mask_count();
25	    SetVectorCount(validRow * validCol);
26	    Op::BinInstr(dstPtr, src0Ptr, src1Ptr, 0);
27	    set_mask_norm();
28	    SetFullVecMaskByDType<T>();
29	}
30	
31	template <typename Op, typename T, unsigned rowStride>
32	PTO_INTERNAL void Bin2LCountMode(
33	    __ubuf__ T* dstPtr, __ubuf__ T* src0Ptr, __ubuf__ T* src1Ptr, unsigned validRow, unsigned validCol)
34	{
35	    set_mask_count();
36	    SetVectorCount(validCol);
37	    for (unsigned i = 0; i < validRow; i++) {
38	        unsigned offset = i * rowStride;
39	        Op::BinInstr(dstPtr + offset, src0Ptr + offset, src1Ptr + offset, 0);
40	    }
41	    set_mask_norm();
42	    SetFullVecMaskByDType<T>();
43	}
44	
45	template <typename Op, typename T, unsigned elementsPerRepeat, unsigned tileCols, uint8_t repeatStride>
46	PTO_INTERNAL void Bin1LNormModeSmall(
47	    __ubuf__ T* dstPtr, __ubuf__ T* src0Ptr, __ubuf__ T* src1Ptr, unsigned validRow, unsigned validCol)
48	{
49	    SetContMaskByDType<T>(validCol);
50	    Op::BinInstr(dstPtr, src0Ptr, src1Ptr, validRow, repeatStride, repeatStride, repeatStride);
51	    SetFullVecMaskByDType<T>();
52	    return;
53	}
54	
55	template <
56	    typename Op, typename T, unsigned elementsPerRepeat, unsigned blockSizeElem, unsigned rowStride, unsigned tileCols>
57	PTO_INTERNAL void Bin1LNormMode(
58	    __ubuf__ T* dstPtr, __ubuf__ T* src0Ptr, __ubuf__ T* src1Ptr, unsigned validRow, unsigned validCol)
59	{
60	    unsigned numElements = validRow * validCol;
61	    unsigned headRepeats = numElements / elementsPerRepeat;
62	    unsigned tailElements = numElements % elementsPerRepeat;
63	    Op::BinInstr(dstPtr, src0Ptr, src1Ptr, headRepeats); // headRepeats can be zero
64	    if (tailElements) [[unlikely]] {
65	        unsigned offset = headRepeats * elementsPerRepeat;
66	        SetContMaskByDType<T>(tailElements);
67	        Op::BinInstr(dstPtr + offset, src0Ptr + offset, src1Ptr + offset, 1);
68	        SetFullVecMaskByDType<T>();
69	    }
70	}
71	
72	template <typename Op, typename T, unsigned elementsPerRepeat, unsigned rowStride>
73	PTO_INTERNAL void Bin2LNormModeColVLAlign(
74	    __ubuf__ T* dstPtr, __ubuf__ T* src0Ptr, __ubuf__ T* src1Ptr, unsigned validRow, unsigned validCol)
75	{
76	    unsigned headRepeats = validCol / elementsPerRepeat;
77	    for (unsigned i = 0; i < validRow; i++) {
78	        unsigned offset = i * rowStride;
79	        Op::BinInstr(dstPtr + offset, src0Ptr + offset, src1Ptr + offset, headRepeats);
80	    }
81	}
82	
83	template <typename Op, typename T, unsigned Rows, unsigned elementsPerRepeat, unsigned blockSizeElem, unsigned stride>
84	PTO_INTERNAL void Bin2LNormModeHead(
85	    __ubuf__ T* dstPtr, __ubuf__ T* src0Ptr, __ubuf__ T* src1Ptr, unsigned validRow, unsigned numRepeatPerLine)
86	{
87	    if (numRepeatPerLine > 0) {
88	        unsigned numLoop = numRepeatPerLine / REPEAT_MAX;
89	        unsigned remainAfterLoop = numRepeatPerLine % REPEAT_MAX;
90	        for (int i = 0; i < validRow; i++) {
91	            if (numLoop) [[unlikely]] {
92	                for (int j = 0; j < numLoop; j++) {
93	                    unsigned offset = i * stride + j * elementsPerRepeat * REPEAT_MAX;
94	                    Op::BinInstr(dstPtr + offset, src0Ptr + offset, src1Ptr + offset, REPEAT_MAX);
95	                }
96	            }
97	            if (remainAfterLoop) {
98	                unsigned offset = i * stride + numLoop * elementsPerRepeat * REPEAT_MAX;
99	                Op::BinInstr(dstPtr + offset, src0Ptr + offset, src1Ptr + offset, remainAfterLoop);
100	            }
101	        }
102	    }
103	}
104	
105	template <typename Op, typename T, unsigned Rows, unsigned elementsPerRepeat, unsigned blockSizeElem, unsigned stride>
106	PTO_INTERNAL void Bin2LNormModeTail(
107	    __ubuf__ T* dstPtr, __ubuf__ T* src0Ptr, __ubuf__ T* src1Ptr, unsigned validRow, unsigned numRemainPerLine)
108	{
109	    unsigned numLoop = 0;
110	    unsigned remainAfterLoop = validRow;
111	    constexpr bool strideOverFlag = (stride / blockSizeElem > REPEAT_STRIDE_MAX);
112	    SetContMaskByDType<T>(numRemainPerLine);
113	    if constexpr (Rows > pto::REPEAT_MAX) {
114	        numLoop = validRow / REPEAT_MAX;
115	        for (int i = 0; i < numLoop; i++) {
116	            if constexpr (strideOverFlag) {
117	                for (uint64_t j = 0; j < REPEAT_MAX; j++) {
118	                    unsigned offset = i * REPEAT_MAX * stride + j * stride;
119	                    Op::BinInstr(dstPtr + offset, src0Ptr + offset, src1Ptr + offset, 1, 1, 1, 1);
120	                }
121	            } else {
122	                unsigned offset = i * REPEAT_MAX * stride;
123	                uint8_t repeatStride = stride / blockSizeElem;
124	                Op::BinInstr(
125	                    dstPtr + offset, src0Ptr + offset, src1Ptr + offset, REPEAT_MAX, repeatStride, repeatStride,
126	                    repeatStride);
127	            }
128	        }
129	        remainAfterLoop = validRow % REPEAT_MAX;
130	    }
131	    if (remainAfterLoop) {
132	        if constexpr (strideOverFlag) {
133	            for (unsigned j = 0; j < remainAfterLoop; j++) {
134	                unsigned offset = numLoop * REPEAT_MAX * stride + j * stride;
135	                Op::BinInstr(dstPtr + offset, src0Ptr + offset, src1Ptr + offset, 1, 1, 1, 1);
136	            }
137	        } else {
138	            unsigned offset = numLoop * REPEAT_MAX * stride;
139	            uint8_t repeatStride = stride / blockSizeElem;
140	            Op::BinInstr(
141	                dstPtr + offset, src0Ptr + offset, src1Ptr + offset, remainAfterLoop, repeatStride, repeatStride,
142	                repeatStride);
143	        }
144	    }
145	    SetFullVecMaskByDType<T>();
146	}
147	
148	template <
149	    typename Op, typename T, unsigned Rows, unsigned elementsPerRepeat, unsigned blockSizeElem, unsigned rowStride>
150	PTO_INTERNAL void Bin2LNormModeRowRpt(
151	    __ubuf__ T* dstPtr, __ubuf__ T* src0Ptr, __ubuf__ T* src1Ptr, unsigned validRow, unsigned validCol)
152	{
153	    constexpr unsigned repeatStride = rowStride / blockSizeElem;
154	    constexpr bool condRowRpt = ((Rows <= pto::REPEAT_MAX) && (repeatStride <= REPEAT_STRIDE_MAX));
155	    if constexpr (condRowRpt) {
156	        unsigned numLoop = validCol / elementsPerRepeat;
157	        unsigned tailElements = validCol % elementsPerRepeat;
158	        for (unsigned i = 0; i < numLoop; i++) {
159	            unsigned offset = i * elementsPerRepeat;
160	            Op::BinInstr(
161	                dstPtr + offset, src0Ptr + offset, src1Ptr + offset, validRow, repeatStride, repeatStride,
162	                repeatStride);
163	        }
164	
165	        if (tailElements) {
166	            unsigned offset = numLoop * elementsPerRepeat;
167	            SetContMaskByDType<T>(tailElements);
168	            Op::BinInstr(
169	                dstPtr + offset, src0Ptr + offset, src1Ptr + offset, validRow, repeatStride, repeatStride,
170	                repeatStride);
171	            SetFullVecMaskByDType<T>();
172	        }
173	    } else {
174	        unsigned numRemainPerLine = validCol;
175	        if constexpr (Rows > elementsPerRepeat) {
176	            unsigned numRepeatPerLine = validCol / elementsPerRepeat;
177	            numRemainPerLine = validCol % elementsPerRepeat;
178	            Bin2LNormModeHead<Op, T, Rows, elementsPerRepeat, blockSizeElem, rowStride>(
179	                dstPtr, src0Ptr, src1Ptr, validRow, numRepeatPerLine);
180	            unsigned offset = numRepeatPerLine * elementsPerRepeat;
181	            dstPtr += offset;
182	            src0Ptr += offset;
183	            src1Ptr += offset;
184	        }
185	        if (numRemainPerLine) {
186	            Bin2LNormModeTail<Op, T, Rows, elementsPerRepeat, blockSizeElem, rowStride>(
187	                dstPtr, src0Ptr, src1Ptr, validRow, numRemainPerLine);
188	        }
189	    }
190	}
191	
192	template <
193	    typename Op, typename T, typename TileData, unsigned elementsPerRepeat, unsigned blockSizeElem, unsigned rowStride>
194	PTO_INTERNAL void BinaryInstrFastPath(
195	    __ubuf__ T* dstPtr, __ubuf__ T* src0Ptr, __ubuf__ T* src1Ptr, unsigned validRow, unsigned validCol)
196	{
197	    constexpr unsigned totalRepeats = (TileData::Rows * TileData::Cols + elementsPerRepeat - 1) / elementsPerRepeat;
198	    constexpr bool nonVLAligned = (((TileData::Cols % elementsPerRepeat) != 0) && (TileData::Cols > elementsPerRepeat));
199	    if constexpr (nonVLAligned || (totalRepeats > pto::REPEAT_MAX)) {
200	        Bin1LCountMode<Op, T>(dstPtr, src0Ptr, src1Ptr, validRow, validCol);
201	    } else {
202	        Bin1LNormMode<Op, T, elementsPerRepeat, blockSizeElem, rowStride, TileData::Cols>(
203	            dstPtr, src0Ptr, src1Ptr, validRow, validCol);
204	    }
205	}
206	
207	template <
208	    typename Op, typename T, typename TileData, unsigned elementsPerRepeat, unsigned blockSizeElem, unsigned rowStride>
209	PTO_INTERNAL void BinaryInstrGeneralPath(
210	    __ubuf__ T* dstPtr, __ubuf__ T* src0Ptr, __ubuf__ T* src1Ptr, unsigned validRow, unsigned validCol)
211	{
212	    // Continuous check in runtime(merge axis)
213	    if ((TileData::Cols == validCol) || (validRow == 1)) [[likely]] {
214	        unsigned totalRepeats = (validRow * validCol + elementsPerRepeat - 1) / elementsPerRepeat;
215	        bool nonVLAligned = ((validCol > elementsPerRepeat) && ((validCol % elementsPerRepeat) != 0));
216	        if (nonVLAligned || (totalRepeats > pto::REPEAT_MAX)) [[unlikely]] {
217	            Bin1LCountMode<Op, T>(dstPtr, src0Ptr, src1Ptr, validRow, validCol);
218	        } else {
219	            Bin1LNormMode<Op, T, elementsPerRepeat, blockSizeElem, rowStride, TileData::Cols>(
220	                dstPtr, src0Ptr, src1Ptr, validRow, validCol);
221	        }
222	    } else { // Non continuous
223	        constexpr unsigned normColRepeat = TileData::Cols / elementsPerRepeat;
224	        if constexpr ((normColRepeat > 1) && ((TileData::Rows * normColRepeat) < SMALL_RPT_BINOP)) {
225	            Bin2LCountMode<Op, T, rowStride>(dstPtr, src0Ptr, src1Ptr, validRow, validCol);
226	        } else if constexpr (TileData::Rows < (normColRepeat + 1)) {
227	            if ((validCol % elementsPerRepeat) > 0) {
228	                Bin2LCountMode<Op, T, rowStride>(dstPtr, src0Ptr, src1Ptr, validRow, validCol);
229	            } else {
230	                Bin2LNormModeColVLAlign<Op, T, elementsPerRepeat, rowStride>(
231	                    dstPtr, src0Ptr, src1Ptr, validRow, validCol);
232	            }
233	        } else {
234	            Bin2LNormModeRowRpt<Op, T, TileData::Rows, elementsPerRepeat, blockSizeElem, rowStride>(
235	                dstPtr, src0Ptr, src1Ptr, validRow, validCol);
236	        }
237	    }
238	}
239	
240	template <
241	    typename Op, typename T, typename TileData, unsigned elementsPerRepeat, unsigned blockSizeElem, unsigned rowStride>
242	PTO_INTERNAL void BinaryInstr(
243	    __ubuf__ T* dstPtr, __ubuf__ T* src0Ptr, __ubuf__ T* src1Ptr, unsigned validRow, unsigned validCol)
244	{
245	    // Small shape optimization
246	    if constexpr ((TileData::Rows <= pto::REPEAT_MAX) && (TileData::Cols < elementsPerRepeat)) {
247	        constexpr uint8_t repeatStride = rowStride / blockSizeElem;
248	        Bin1LNormModeSmall<Op, T, elementsPerRepeat, TileData::Cols, repeatStride>(
249	            dstPtr, src0Ptr, src1Ptr, validRow, validCol);
250	        return;
251	    }
252	    // Continuous check in compile time
253	    if constexpr ((TileData::Cols == TileData::ValidCol) || (TileData::Rows == 1)) {
254	        BinaryInstrFastPath<Op, T, TileData, elementsPerRepeat, blockSizeElem, rowStride>(
255	            dstPtr, src0Ptr, src1Ptr, validRow, validCol);
256	    } else {
257	        BinaryInstrGeneralPath<Op, T, TileData, elementsPerRepeat, blockSizeElem, rowStride>(
258	            dstPtr, src0Ptr, src1Ptr, validRow, validCol);
259	    }
260	}
261	
262	// support different tile shape of dst, src0, src1
263	template <
264	    typename Op, typename T, unsigned elemPerRpt, unsigned elemPerBlk, unsigned dstStride,
265	    unsigned src0Stride = dstStride, unsigned src1Stride = dstStride>
266	PTO_INTERNAL void Bin2LNormModeHead(
267	    __ubuf__ T* dst, __ubuf__ T* src0, __ubuf__ T* src1, unsigned validRow, unsigned rptPerLine)
268	{
269	    if (rptPerLine > 0) {
270	        unsigned numLoop = rptPerLine / REPEAT_MAX;
271	        unsigned remainAfterLoop = rptPerLine % REPEAT_MAX;
272	        for (int i = 0; i < validRow; i++) {
273	            if (numLoop) [[unlikely]] {
274	                for (int j = 0; j < numLoop; j++) {
275	                    unsigned dstOffset = i * dstStride + j * elemPerRpt * REPEAT_MAX;
276	                    unsigned src0Offset = i * src0Stride + j * elemPerRpt * REPEAT_MAX;
277	                    unsigned src1Offset = i * src1Stride + j * elemPerRpt * REPEAT_MAX;
278	                    Op::BinInstr(dst + dstOffset, src0 + src0Offset, src1 + src1Offset, REPEAT_MAX);
279	                }
280	            }
281	            if (remainAfterLoop) {
282	                unsigned offset = i * dstStride + numLoop * elemPerRpt * REPEAT_MAX;
283	                unsigned src0Offset = i * src0Stride + numLoop * elemPerRpt * REPEAT_MAX;
284	                unsigned src1Offset = i * src1Stride + numLoop * elemPerRpt * REPEAT_MAX;
285	                Op::BinInstr(dst + offset, src0 + src0Offset, src1 + src1Offset, remainAfterLoop);
286	            }
287	        }
288	    }
289	}
290	
291	template <
292	    typename Op, typename T, unsigned elemPerRpt, unsigned elemPerBlk, unsigned dstStride, unsigned src0Stride,
293	    unsigned src1Stride>
294	PTO_INTERNAL void Bin2LNormModeTail(
295	    __ubuf__ T* dst, __ubuf__ T* src0, __ubuf__ T* src1, unsigned validRow, unsigned remain)
296	{
297	    unsigned numLoop = validRow / REPEAT_MAX;
298	    unsigned remainAfterLoop = validRow % REPEAT_MAX;
299	    constexpr bool src0StrideOverFlag = (src0Stride / elemPerBlk > REPEAT_STRIDE_MAX);
300	    constexpr bool src1StrideOverFlag = (src1Stride / elemPerBlk > REPEAT_STRIDE_MAX);
301	    constexpr bool dstStrideOverFlag = (dstStride / elemPerBlk > REPEAT_STRIDE_MAX);
302	    SetContMaskByDType<T>(remain);
303	    for (int i = 0; i < numLoop; i++) {
304	        if constexpr (src0StrideOverFlag || src1StrideOverFlag || dstStrideOverFlag) {
305	            for (uint64_t j = 0; j < REPEAT_MAX; j++) {
306	                unsigned src0Offset = i * REPEAT_MAX * src0Stride + j * src0Stride;
307	                unsigned src1Offset = i * REPEAT_MAX * src1Stride + j * src1Stride;
308	                unsigned dstOffset = i * REPEAT_MAX * dstStride + j * dstStride;
309	                Op::BinInstr(dst + dstOffset, src0 + src0Offset, src1 + src1Offset, 1, 1, 1, 1);
310	            }
311	        } else {
312	            unsigned src0Offset = i * REPEAT_MAX * src0Stride;
313	            unsigned src1Offset = i * REPEAT_MAX * src1Stride;
314	            unsigned dstOffset = i * REPEAT_MAX * dstStride;
315	            uint8_t src0BlkPerLine = src0Stride / elemPerBlk;
316	            uint8_t src1BlkPerLine = src1Stride / elemPerBlk;
317	            uint8_t dstBlkPerLine = dstStride / elemPerBlk;
318	            Op::BinInstr(
319	                dst + dstOffset, src0 + src0Offset, src1 + src1Offset, REPEAT_MAX, dstBlkPerLine, src0BlkPerLine,
320	                src1BlkPerLine);
321	        }
322	    }
323	    remainAfterLoop = validRow % REPEAT_MAX;
324	    if (remainAfterLoop) {
325	        if constexpr (src0StrideOverFlag || src1StrideOverFlag || dstStrideOverFlag) {
326	            for (unsigned j = 0; j < remainAfterLoop; j++) {
327	                unsigned src0Offset = numLoop * REPEAT_MAX * src0Stride + j * src0Stride;
328	                unsigned src1Offset = numLoop * REPEAT_MAX * src1Stride + j * src1Stride;
329	                unsigned dstOffset = numLoop * REPEAT_MAX * dstStride + j * dstStride;
330	                Op::BinInstr(dst + dstOffset, src0 + src0Offset, src1 + src1Offset, 1, 1, 1, 1);
331	            }
332	        } else {
333	            unsigned dstOffset = numLoop * REPEAT_MAX * dstStride;
334	            unsigned src0Offset = numLoop * REPEAT_MAX * src0Stride;
335	            unsigned src1Offset = numLoop * REPEAT_MAX * src1Stride;
336	            uint8_t dstBlkPerLine = dstStride / elemPerBlk;
337	            uint8_t src0BlkPerLine = src0Stride / elemPerBlk;
338	            uint8_t src1BlkPerLine = src1Stride / elemPerBlk;
339	            Op::BinInstr(
340	                dst + dstOffset, src0 + src0Offset, src1 + src1Offset, remainAfterLoop, dstBlkPerLine, src0BlkPerLine,
341	                src1BlkPerLine);
342	        }
343	    }
344	    SetFullVecMaskByDType<T>();
345	}
346	
347	template <
348	    typename Op, typename T, unsigned elemPerRpt, unsigned elemPerBlk, unsigned dstStride, unsigned src0Stride,
349	    unsigned src1Stride>
350	PTO_INTERNAL void Bin2LNormModeRowRpt(
351	    __ubuf__ T* dst, __ubuf__ T* src0, __ubuf__ T* src1, unsigned validRow, unsigned validCol)
352	{
353	    unsigned rptPerLine = validCol / elemPerRpt;
354	    unsigned remain = validCol % elemPerRpt;
355	    Bin2LNormModeHead<Op, T, elemPerRpt, elemPerBlk, dstStride, src0Stride, src1Stride>(
356	        dst, src0, src1, validRow, rptPerLine);
357	    if (remain) {
358	        unsigned offset = rptPerLine * elemPerRpt;
359	        dst += offset;
360	        src0 += offset;
361	        src1 += offset;
362	        Bin2LNormModeTail<Op, T, elemPerRpt, elemPerBlk, dstStride, src0Stride, src1Stride>(
363	            dst, src0, src1, validRow, remain);
364	    }
365	}
366	
367	template <
368	    typename Op, typename T, unsigned elementsPerRepeat, unsigned blockSizeElem, unsigned dstRowStride,
369	    unsigned src0RowStride, unsigned src1RowStride>
370	PTO_INTERNAL void BinaryInstr(
371	    __ubuf__ T* dst, __ubuf__ T* src0, __ubuf__ T* src1, unsigned validRows, unsigned validCols)
372	{
373	    Bin2LNormModeRowRpt<Op, T, elementsPerRepeat, blockSizeElem, dstRowStride, src0RowStride, src1RowStride>(
374	        dst, src0, src1, validRows, validCols);
375	}
376	
377	} // namespace pto
378	#endif
